contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // This test takes two parameters:
    // - fundAmount: Ether this test contract will hold so it can forward a wager amount to c if needed
    // - wagerAmount: amount to send when calling wager(); if it equals c.currentBetLimit() and the contract is open,
    //   the wager() call may succeed. We allow the caller to supply any values; behavior (revert/succeed) is observed.
    function run(uint256 fundAmount, uint256 wagerAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (wagerAmount)); require(wagerAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= fundAmount);

        // Ensure this contract has the funds it intends to forward: no-op if fundAmount==0 or already present.
        // (We cannot transfer to ourselves; assume test harness funds this contract before calling run.)

        // Read pre-call observables
        uint256 beforeBalance = address(c).balance;

        // Attempt to place a wager by making the top-level state-changing call.
        // We must send exactly wagerAmount from this contract to c; ensure we have it.
        require(address(this).balance >= wagerAmount);
        bool wagerReverted;
        c.wager{value: wagerAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            wagerReverted = true;
        } else {
            wagerReverted = false;
        }

        // Attempt to play: top-level state-changing call, record whether it reverts.
        bool playReverted;
        c.play(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            playReverted = true;
        } else {
            playReverted = false;
        }

        // Read post-call observables
        uint256 afterBalance = address(c).balance;
        uint256 winnersPot = c.winnersPot(); if (__ESBMC_reverted()) return; // view
        bool hasWager = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return; // view

        // General property: If play() did not revert, then the caller's wager must have been cleared
        // (hasPlayerWagered == false) and winnersPot equals half of the contract balance.
        assert(playReverted || (hasWager == false && winnersPot * 2 == afterBalance));
    }

    receive() external payable {}
}

