pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 fundAmount, uint256 wagerAmount) internal {
        wagerAmount = bound(wagerAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fundAmount);
        uint256 beforeBalance = address(c).balance;
        vm.assume(address(this).balance >= wagerAmount);
        bool wagerReverted;
        try c.wager{value: wagerAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }
        uint256 afterBalance = address(c).balance;
        uint256 winnersPot;
        try c.winnersPot() returns (uint256 __r) { winnersPot = __r; } catch { return; }
        bool hasWager;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { hasWager = __r; } catch { return; }
        assertTrue(playReverted || (hasWager == false && winnersPot * 2 == afterBalance));
    }

    function testFuzz_run(uint256 fundAmount, uint256 wagerAmount) public {
        _run(fundAmount, wagerAmount);
    }

    receive() external payable {}
}
